# Generated by scripts/homebrew-formulas.py in tinhthanh/shipyard for v0.3.31-fork.10.
class Vetgo < Formula
  desc "Run coding agents on your own boxes: the berth CLI and laptop agent"
  homepage "https://github.com/tinhthanh/shipyard"
  version "0.3.31-fork.10"
  license "MIT"

  on_macos do
    on_arm do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.10/berth-darwin-arm64.tar.gz"
      sha256 "62a13610198a2f460700c9f9bee5f72260fa2e68115264dd54df070415cfce04"
    end
    on_intel do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.10/berth-darwin-amd64.tar.gz"
      sha256 "d4a56a13c3297035f8ae7657df70f3a605cd7fc0144e33d97027c747deee097e"
    end

    # The berthd builds `berth upgrade` puts on Mac boxes; the Linux ones
    # come in berth's own archive.
    resource "berthd-darwin-arm64" do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.10/berthd-darwin-arm64.tar.gz"
      sha256 "f5ca5036bbe32bdd38be966a101319a363c2facfceffdc4b8538ea4ca088b939"
    end
    resource "berthd-darwin-amd64" do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.10/berthd-darwin-amd64.tar.gz"
      sha256 "b07891a6570626b79cab767b5752f813de6bd60b7dd392a7124b7359b6a3c210"
    end
  end
  on_linux do
    on_arm do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.10/berth-linux-arm64.tar.gz"
      sha256 "7b3e39a9f100734c5ce8a3683e7af69a6412ba7a0d2d146e329a007e842ec663"
    end
    on_intel do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.10/berth-linux-amd64.tar.gz"
      sha256 "506a21f6947cd06d978210e0637def880aebc7a3c595a0cee817c1bcffa7e4ca"
    end
  end

  def install
    # berth looks beside its own file (through the link in bin) for the
    # berthd and tmux builds it uploads to boxes.
    libexec.install Dir["*"]
    if OS.mac?
      %w[arm64 amd64].each do |arch|
        resource("berthd-darwin-#{arch}").stage { libexec.install "berthd" => "berthd-darwin-#{arch}" }
      end
    end
    bin.install_symlink libexec/"berth"
  end

  def caveats
    <<~EOS
      Start the laptop agent, and have it start when you log in:
        berth agent install
      Add a box: berth add ssh USER@HOST (see berth help).
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/berth version")
  end
end
